<?php
declare(strict_types=1);require __DIR__.'/includes/ui.php';$u=msw_require_user();$uid=(int)$u['id'];$rd=msw_one("SELECT level,score,grade FROM base_sectors WHERE user_id=? AND sector_key='rd'",'i',[$uid])?:['level'=>1,'score'=>0,'grade'=>'E--'];$inv=msw_inventory($uid);
if(msw_is_post()){msw_verify_post();$key=(string)($_POST['recipe']??'');$cat=msw_rd_catalog();if(!isset($cat[$key]))msw_flash('Unknown R&D recipe.','error');elseif((int)$rd['level']<(int)$cat[$key]['rd'])msw_flash('R&D level requirement not met.','error');elseif(!msw_spend_resources($uid,$cat[$key]['cost']))msw_flash('Insufficient base materials.','error');else{msw_add_item($uid,$key,(int)$cat[$key]['quantity']);msw_console_event_for_user($uid,'R&D','MANUFACTURE',$cat[$key]['name'].' manufactured x'.(int)$cat[$key]['quantity'].'.',['recipe'=>$key,'quantity'=>(int)$cat[$key]['quantity'],'rd_level'=>(int)$rd['level']]);msw_flash($cat[$key]['name'].' manufactured.','success');}msw_redirect('rd.php');}
msw_header('R&D Laboratory','base.php');msw_alert(msw_flash());msw_resource_strip($uid);?><section class="hero"><div class="eyebrow">R&D TEAM // LEVEL <?=intval($rd['level'])?> // <?=msw_e($rd['grade'])?></div><h1>RESEARCH & <span>DEVELOPMENT</span></h1><p>Manufacturing availability is derived from your R&D Team level. Materials are debited atomically before items enter persistent inventory.</p></section><div class="grid g3" style="margin-top:18px"><?php foreach(msw_rd_catalog() as $key=>$r):$locked=(int)$rd['level']<(int)$r['rd'];?><article class="panel"><div class="panel-body"><span class="badge">R&D <?=intval($r['rd'])?></span><h3><?=msw_e($r['name'])?></h3><p><?=msw_e($r['desc'])?></p><p><small>COST · <?php foreach($r['cost'] as $k=>$v):?><?=msw_e(strtoupper(str_replace('_',' ',$k)))?> <?=number_format($v)?> &nbsp; <?php endforeach;?></small></p><p>Inventory: <b><?=intval($inv[$key]??0)?></b></p><form method="post"><?=msw_csrf_field()?><input type="hidden" name="recipe" value="<?=msw_e($key)?>"><button <?=$locked?'disabled':''?>><?=$locked?'LOCKED':'Manufacture x'.intval($r['quantity'])?></button></form></div></article><?php endforeach;?></div><?php msw_footer();?>
